#!/usr/bin/env python3
"""Read-only check of the prepared guest files used for this memory audit."""
import hashlib
import json
from pathlib import Path
import sys

MESA = '541c56aa3fd24027ed46ae350287d21dcd56c901'
DECODER = 'f0ce013371a68e85b5a1a1b0cf14ac9ad729f4be'
PREFIX = 'src/gfxstream/guest/vulkan_enc/'
EXPECTED = {
    'ResourceTracker.cpp': '6ba70e89dc7939c8529860829af9a11d25923666331b8555e8178ebf2a2b132f',
    'autogenerated/VkEncoder.cpp': '37c3f4dced1c44f581d3679321629c0316152795abca6a030cdc892f5e85dbb9',
    'autogenerated/func_table.cpp': '513778a26977def8417633b56d33d076712b4c83a9d21e6abc251e17bd861e05',
}

def verify(root):
    result = {}
    for name, expected in EXPECTED.items():
        actual = hashlib.sha256((Path(root) / PREFIX / name).read_bytes()).hexdigest()
        if actual != expected:
            raise ValueError(f'{name}: audited source hash mismatch ({actual})')
        result[name] = actual
    return result

if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit('usage: verify_sources.py PREPARED_MESA_TREE')
    print(json.dumps({'audited_files': verify(sys.argv[1]), 'mesa_pin': MESA,
                      'decoder_pin': DECODER, 'runtime_verified': False}, indent=2))
